  "plans.backToWelcome": "Retour à la bienvenue",
  "plans.eyebrow": "Forfaits et fonctionnalités",
  "plans.title": "Comparer les forfaits StockHaven",
  "plans.intro": "Un seul compte, quel que soit le forfait choisi — Affaires couvre jusqu’à cinq entreprises. Les prix sont mensuels en dollars américains, et les nouveaux clients admissibles du site Web peuvent recevoir un essai de sept jours pour Essentiel et Affaires. Passer d’un abonnement Essentiel existant à Affaires ne redémarre pas l’essai et ne crée pas un autre essai gratuit. Les prix des forfaits du site Web sont avant les taxes applicables, s’il y en a. Votre débit exact sera affiché avant que vous autorisiez un abonnement.",
  "plans.availableAtLaunch": "Offert au lancement mobile",
