  "plans.included": "Inclus",
  "plans.notIncluded": "Non inclus",
  "plans.mobileIncludedNote": "Les deux forfaits du site Web comprennent le compagnon mobile, donc un abonné du site Web ne paie jamais les frais mensuels du mobile en plus.",
  "plans.priceNote": "Essentiel coûte 14,99 $/mois plus les taxes applicables, s’il y en a. Affaires coûte 29,99 $/mois plus les taxes applicables, s’il y en a. Toute taxe requise est déterminée pendant le paiement chez le fournisseur et doit apparaître dans le total final avant le paiement. Cette page de comparaison n’est pas une estimation de taxes ni une autorisation de paiement.",
  "plans.mobilePriceNote": "Le forfait mobile seulement coûte 4,99 $/mois à son prix de base américain prévu. L’App Store ou Google Play affiche le prix réel de l’abonnement local et les taxes applicables avant l’achat. Ses limites de produits, de sites et de personnel sont fixées au lancement, séparément des niveaux du site Web.",
  "plans.planChangeNote": "Un changement de forfait du site Web doit être confirmé par le fournisseur de facturation. Le nouveau prix, la date d’entrée en vigueur et toute proratisation seront expliqués avant que le changement soit autorisé. Une mise à niveau ne devrait pas créer un deuxième abonnement.",
  "plans.providerNote": "Les prix, les débits et les essais sont gérés par le fournisseur par lequel vous vous abonnez — l’App Store, Google Play, le site Web ou Shopify — jamais par cette page.",
