  "upgrade.previewDowngradeNote": "Une rétrogradation prend effet à la fin de votre période payée. Vos données des fonctionnalités perdues sont conservées, mais inaccessibles — elles ne sont jamais supprimées comme effet secondaire d’une rétrogradation.",
