  "reports.movementsCapped": "Seules les {cap} entrées les plus récentes du registre ont été lues, donc les mouvements plus anciens ne figurent pas dans les totaux. Resserrez la période pour voir les chiffres exacts d’une fenêtre.",
  "reports.footnote": "Les ventes utilisent le prix de détail actuel de chaque produit, les réceptions utilisent le coût enregistré quand le stock est arrivé, et les pertes utilisent le coût unitaire actuel. L’argent manquant n’est jamais traité comme zéro — laissez un champ vide tant que le chiffre n’est pas connu. Un rapport est une vue, et non un document : rien n’est écrit dans vos dossiers quand vous en exécutez un.",
