  "valuation.noRetailPrice": "aucun prix de détail",
  "valuation.footnote": "La valeur au coût utilise le coût unitaire actuel de chaque produit, donc recevoir à un nouveau prix réévalue toute la tablette. Les unités retenues sont quand même comptées ici — elles sont en main, simplement promises à une commande. L’argent manquant n’est jamais traité comme zéro; laissez un champ vide tant que le chiffre n’est pas connu.",
