  "recovery.emailMeCodeHint": "Si vous avez configuré un courriel de secours, nous y enverrons un code à 6 chiffres. Pour protéger votre compte, cette page répond toujours de la même façon — qu’un code ait été envoyé ou non.",
  "recovery.codeSent": "Si votre courriel de secours est au dossier, un code à 6 chiffres est en route vers là maintenant. Il expire dans 10 minutes.",
