  "print.style.title": "Style des documents",
  "print.style.desc": "Faites de vos documents les vôtres. Ces choix habillent votre facture, votre reçu, votre bon de livraison, vos documents de retour, vos fiches produits, vos feuilles de comptage et vos listes de préparation — et ils sont retenus pour votre entreprise.",
