  "staffLib.perm.locationsCreate": "Ajouter des emplacements",
  "staffLib.area.locationsAccess": "Ajout d’emplacements",
  "staff.memberDialog.locationsAccessHint": "Avec cette case cochée, cette personne peut ajouter de nouveaux emplacements. Sans elle, seul le propriétaire peut ajouter un emplacement, et les boutons d’ajout ne s’affichent pas pour elle.",
  "apiErrors.locationsCreateReserved": "Seul le propriétaire, ou un membre de l’équipe que le propriétaire a autorisé à ajouter des emplacements, peut ajouter un emplacement.",
  "settings.policies.title": "Politiques et conditions de votre magasin",
  "settings.policies.ownerDescription": "Votre magasin, vos règles. Écrivez ici les politiques de votre magasin et vos conditions générales : tapez-les, ou téléversez un fichier. Chaque nouveau membre de l’équipe les voit une fois à son arrivée, et toute votre équipe peut les lire ici à tout moment. Vous seul pouvez les modifier.",
  "settings.policies.memberDescription": "Les politiques et conditions propres à votre magasin, écrites par le propriétaire. Seul le propriétaire peut les modifier.",
  "settings.policies.storePolicies": "Politiques du magasin",
  "settings.policies.termsConditions": "Conditions générales",
  "settings.policies.policiesHint": "Les règles de la maison pour votre magasin — comment le magasin fonctionne et comment l’application y est utilisée. Toute la politique de votre magasin peut vivre ici.",
  "settings.policies.termsHint": "Les conditions générales propres à votre magasin, dans vos propres mots.",
  "settings.policies.policiesPlaceholder": "Tapez les politiques de votre magasin…",
  "settings.policies.termsPlaceholder": "Tapez vos conditions générales…",
