  "settings.policyQuiz.hint": "Écrivez des questions sur ce document pour votre équipe. Une personne y répond dans Formation lorsque vous cochez cette formation pour elle dans sa fiche Personnel. Il n'y a aucune limite au nombre de questions que vous pouvez écrire.",
