  "settings.policyQuiz.saved": "Questions enregistrées.",
  "settings.policyQuiz.title": "Questions pour votre équipe",
  "staff.memberDialog.trainingAccessHint": "La lecture des politiques du magasin et des conditions est pour tout le monde. Ces cases attribuent les formations avec quiz que le propriétaire crée à côté de chaque document dans Réglages.",
  "staffLib.area.trainingAccess": "Formations avec quiz sur les politiques",
  "staffLib.perm.trainingPoliciesQuiz": "Formation avec quiz sur les politiques du magasin",
  "staffLib.perm.trainingTermsQuiz": "Formation avec quiz sur les conditions générales",
  "training.comment.placeholder": "Quelque chose à dire sur cette leçon…",
  "training.comment.send": "Envoyer le commentaire",
  "training.comment.sent": "Votre commentaire a été transmis au propriétaire.",
  "training.comment.title": "Laisser un commentaire pour le propriétaire",
  "training.lessons.download-app.step1": "Luminous StockHaven peut vivre sur votre téléphone ou votre ordinateur comme une vraie application — pas besoin de passer par un magasin d'applications.",
  "training.lessons.download-app.step2": "Ouvrez Réglages et trouvez la carte Télécharger l'application. Elle est là pour chaque rôle, sur les deux forfaits.",
  "training.lessons.download-app.step3": "Touchez le bouton d'installation et suivez les instructions de votre appareil. L'application arrive sur votre écran d'accueil avec le nom et l'icône du magasin.",
  "training.lessons.download-app.step4": "Ouvrez-la ensuite depuis votre écran d'accueil — elle vous connecte de la même façon et affiche le même magasin.",
  "training.lessons.download-app.title": "Télécharger l'application sur votre appareil",
  "training.lessons.mgr-tax-rate.step1": "Les commandes peuvent comporter un taux de taxe de vente. Le propriétaire définit le taux lui-même dans Réglages ; c'est un seul taux pour toute le magasin.",
  "training.lessons.mgr-tax-rate.step2": "Lorsque le propriétaire coche la section taxes pour vous dans votre fiche Personnel, le taux apparaît aussi dans vos Réglages, et vous pouvez le tenir à jour là.",
  "training.lessons.mgr-tax-rate.step3": "Le taux est un pourcentage — 8.25 signifie que le client paie 8.25% de taxe en plus des articles de la commande.",
  "training.lessons.mgr-tax-rate.step4": "Lorsque le taux change, les nouvelles commandes utilisent le nouveau taux. Les commandes déjà passées gardent le taux avec lequel elles ont été faites.",
  "training.lessons.mgr-tax-rate.step5": "Si le propriétaire passe la taxe à Automatique, une nouvelle commande remplit sa taxe avec le taux de base de l'État du client dès que l'État figure sur la commande, et la remplit de nouveau si l'État change. Ce sont des taux de base d'État ; les taxes locales peuvent s'ajouter. Une commande sans État, ou hors des États-Unis, utilise le taux fixe du magasin — et une taxe saisie sur une commande l'emporte toujours.",
  "training.lessons.mgr-tax-rate.title": "Le taux de taxe du magasin",
  "training.lessons.owner-confidentiality.step5": "Voici toute la carte. Votre équipe voit son propre travail — son horaire, ses tâches, ses fiches de paie, ses messages, et les écrans du magasin que son rôle ouvre. Elle ne voit jamais votre essai, le forfait de l'entreprise, ce que le forfait coûte, si un paiement est passé, ou qu'une limite du forfait a été atteinte. Les surfaces d'argent — facturation, factures, moyens de paiement — sont réservées au propriétaire, toujours.",
  "training.lessons.owner-confidentiality.step6": "Si le compte est un jour arrêté, voici le message exact que votre équipe voit : “Les modifications sont désactivées pour le moment. Rien ne peut être ajouté ni modifié en ce moment — demandez au propriétaire de l’entreprise si vous avez besoin de quelque chose.” Rien dans ce message ne nomme un forfait, un prix ou un paiement.",
  "training.lessons.owner-confidentiality.step7": "Et lorsque c'est une limite du forfait qui bloque quelque chose, voici le message exact : “Cela ne peut pas être ajouté pour le moment — demandez au propriétaire de l’entreprise.” Il ne dit jamais qu'une limite a été atteinte — cela reste entre vous et l'application.",
  "training.lessons.staff-builds.step1": "Un assemblage regroupe des produits en une seule chose à vendre — un lot, un kit, un coffret cadeau. Les assemblages vivent dans l'écran Assemblages du menu.",
  "training.lessons.staff-builds.step2": "Ouvrez un assemblage pour voir ce qui le compose : chaque produit composant et combien de chacun l'assemblage utilise.",
  "training.lessons.staff-builds.step3": "Lorsqu'un assemblage est fabriqué ou vendu, le stock de ses composants bouge avec lui — l'application garde les comptes justes pour vous.",
  "training.lessons.staff-builds.step4": "Si un composant manque ou qu'un compte semble faux, dites-le à votre responsable plutôt que de deviner — les assemblages touchent beaucoup de produits à la fois.",
  "training.lessons.staff-builds.title": "Assemblages et lots",
  "training.lessons.staff-cross-store.step1": "Lorsque votre entreprise a plus d'un magasin ou d'un site, les magasins peuvent se demander du stock entre elles. Ces demandes arrivent dans la boîte de réception inter-magasins.",
  "training.lessons.staff-cross-store.step2": "Ouvrez la boîte de réception depuis le menu pour voir ce qu'une autre boutique demande, et ce qui a été envoyé à votre magasin.",
  "training.lessons.staff-cross-store.step3": "Répondez à une demande uniquement de la façon que votre responsable vous a montrée — envoyer du stock modifie les comptes de votre propre boutique.",
  "training.lessons.staff-cross-store.step4": "Si une demande semble fausse — le mauvais article, ou plus que ce que vous avez — ne devinez pas. Signalez-la à votre responsable.",
  "training.lessons.staff-cross-store.title": "La boîte de réception inter-magasins",
  "training.lessons.staff-reports.step1": "Les rapports rassemblent les chiffres du magasin — ventes, stock et plus — en un seul endroit. Les rapports vivent dans le menu.",
  "training.lessons.staff-reports.step2": "Ouvrez un rapport pour voir ses chiffres pour les dates qu'il couvre. Les dates font partie du rapport : le même rapport sur une autre semaine raconte une autre histoire.",
  "training.lessons.staff-reports.step3": "Certains rapports peuvent être enregistrés hors de l'application sous forme de fichiers. N'enregistrez un rapport que lorsque votre responsable ou le propriétaire vous l'a demandé.",
  "training.lessons.staff-reports.step4": "Les chiffres des rapports viennent du vrai travail du magasin — commandes, comptages et mouvements — donc des saisies honnêtes partout ailleurs gardent les rapports justes.",
  "training.lessons.staff-reports.title": "Lire les rapports",
  "training.lessons.welcome-basics.step6": "Lorsque vous avez terminé, déconnectez-vous : un lien Se déconnecter se trouve tout en bas de chaque page, juste au-dessus de la ligne de droits d'auteur. Se déconnecter vous déconnecte partout, sur chaque appareil — ainsi personne ne peut entrer dans votre compte sur un écran partagé.",
  "training.policy.belowLine": "C'est en dessous du seuil — réessayez.",
