  "apiErrors.notFound.photoFound": "Photo introuvable.",
  "apiErrors.profileOwnerNameOnly": "Seul le propriétaire de l'entreprise peut définir le nom du propriétaire.",
  "apiErrors.profilePhotosApproveOwnerOnly": "Seul le propriétaire de l'entreprise peut approuver les photos de l'équipe.",
  "apiErrors.profilePhotosNoneWaiting": "Ce membre de l'équipe n'a aucune photo en attente d'approbation.",
  "apiErrors.profileOwnerNameTooLong": "Limitez votre nom à 80 caractères ou moins.",
  "training.lessons.your-profile-photo.title": "Votre photo de profil",
  "training.lessons.your-profile-photo.step1": "Votre photo apparaît à côté de votre nom en haut de l'application, sur la page Personnel et à côté de vos messages — une fois que le propriétaire l'a approuvée. D'ici là, seules vos initiales s'affichent.",
  "training.lessons.your-profile-photo.step2": "Ouvrez Réglages et trouvez Votre photo de profil. Choisissez une photo de vous et envoyez-la. Elle est transmise au propriétaire pour approbation — elle n'apparaît nulle part pendant l'attente.",
  "training.lessons.your-profile-photo.step3": "Lorsque le propriétaire l'approuve, votre cloche sonne et votre photo commence à s'afficher. Si elle n'est pas approuvée, choisissez une photo différente et envoyez celle-là à la place.",
  "training.lessons.your-profile-photo.step4": "Changer de photo fonctionne de la même façon : la nouvelle est en attente d'approbation, et votre photo actuelle reste en place jusqu'à ce que la nouvelle soit approuvée. Si un changement n'est pas approuvé, vous conservez l'autre.",
  "training.lessons.owner-profile-photos.title": "Photos de profil et votre nom",
  "training.lessons.owner-profile-photos.step1": "La photo de chaque personne s'affiche à côté de son nom en haut de l'application, sur votre page Personnel et à côté de ses messages. La photo d'un membre de l'équipe n'apparaît nulle part tant que vous ne l'avez pas approuvée — l'approbation vous appartient à vous seul, et personne ne peut approuver sa propre photo.",
  "training.lessons.owner-profile-photos.step2": "Lorsque quelqu'un envoie une photo, votre cloche sonne. Ouvrez la page Personnel pour la voir, puis choisissez Approuver ou Ne pas approuver. Si vous ne l'approuvez pas, la personne est invitée à choisir une autre photo.",
  "training.lessons.owner-profile-photos.step3": "Si une personne change de photo, la nouvelle attend votre approbation de la même façon. Sa photo actuelle reste en place pendant l'attente — et demeure si vous n'approuvez pas le changement.",
  "training.lessons.owner-profile-photos.step4": "Votre propre photo ne requiert aucune approbation : définissez-la dans Réglages, sous Votre photo de profil. La même carte contient votre nom — le nom que vous définissez là remplace le mot Propriétaire partout où votre équipe le voit, dans l'application et dans Messages.",
  "payroll.dd.corrected": "Formulaire corrigé",
  "payroll.dd.correctedDone": "Vos coordonnées corrigées ont été envoyées au propriétaire.",
  "payroll.dd.correctionNotice": "Le propriétaire vous a renvoyé votre formulaire pour que vous le corrigiez. Vérifiez chaque chiffre, signez, puis envoyez-le de nouveau.",
  "payroll.dd.correctionWaiting": "Renvoyé — en attente de son formulaire corrigé",
  "payroll.dd.fixHelp": "Si un chiffre est faux, corrigez vos coordonnées et renvoyez le formulaire. Votre nouveau formulaire signé remplace l’ancien, et le propriétaire est informé qu’il a été corrigé.",
