  "staff.memberDialog.clockAccessHint": "Gestionnaires seulement — deux coches séparées. Tableau de pointage et oublis de départ permet à ce gestionnaire de voir les entrées de temps de l’équipe et de corriger les entrées de temps depuis la page Personnel. Appels permet à ce gestionnaire d’ouvrir des fenêtres d’appel, permettant à quelqu’un de travailler alors qu’aucun service ne le prévoit. Ces coches ne font rien pour le personnel.",
