  "apiErrors.notFound.timeEntryFound": "Entrée de temps introuvable.",
  "training.lessons.mgr-clock-callin.title": "Appels et corrections de pointage",
  "training.lessons.mgr-clock-callin.step1": "Le propriétaire peut donner à un gestionnaire deux coches séparées. Appels vous permet d’ouvrir une fenêtre d’appel pour un membre du personnel, et Tableau de pointage et oublis de départ vous permet de voir le tableau de pointage de l’équipe et de corriger les entrées de temps depuis la page Personnel. Chaque coche fonctionne seule — un gestionnaire peut en avoir une sans l’autre.",
  "training.lessons.mgr-clock-callin.step2": "Une fenêtre d’appel permet à une personne de se connecter et de pointer son arrivée quand aucun service ne la couvre. Ouvrez-la depuis la page Personnel, sur la carte Appels et départs non pointés.",
  "training.lessons.mgr-clock-callin.step3": "La fenêtre reste ouverte jusqu’à ce que cette personne pointe son départ — le délai habituel de 10 minutes avant la déconnexion suit — ou jusqu’à ce que vous ou le propriétaire la fermiez plus tôt. Rien ne la ferme tout seul.",
  "training.lessons.mgr-clock-callin.step4": "Quand quelqu’un oublie de pointer son départ, son entrée est signalée sur la page Personnel et dans la Paie une fois le service planifié terminé, et vous et le propriétaire recevez une cloche. L’entrée continue de compter jusqu’à sa correction.",
  "training.lessons.mgr-clock-callin.step5": "Corrigez l’entrée depuis la page Personnel : réglez l’arrivée, le départ et les heures de pause. Un gestionnaire ne corrige que les entrées du personnel — les entrées d’un gestionnaire sont corrigées par le propriétaire.",
  "staffLib.perm.staffDocuments": "Documents du personnel",
  "staffLib.area.documentsAccess": "Documents du personnel",
  "staff.memberDialog.documentsAccessHint": "Gestionnaires seulement — avec cette coche, ce gestionnaire peut ouvrir les dossiers de documents des membres du personnel : les papiers conservés pour chaque personne, comme les formulaires W-4, les candidatures et les copies de pièce d’identité. On vous demandera d’abord de confirmer — ces dossiers contiennent des numéros de sécurité sociale et des dates de naissance. Cette coche ne fait rien pour le personnel.",
  "staff.documentsWarning.body": "Cette personne pourra voir des informations confidentielles sur les membres de votre personnel, y compris les numéros de sécurité sociale et les dates de naissance.",
  "staff.documentsWarning.confirm": "Oui, je comprends",
  "staff.documents.title": "Documents du personnel",
  "staff.documents.desc": "Les papiers que vous conservez pour chaque personne — formulaires W-4, candidatures, formulaires fiscaux, copies de pièce d’identité. Seuls vous, et un gestionnaire à qui vous donnez la coche Documents du personnel, pouvez ouvrir ces dossiers.",
