  "nav.xstoreMessages": "Messages entre succursales",
  "plansLib.businessIncludes.xstoreMessages": "Messages entre succursales — toute votre équipe, dans toutes vos entreprises",
  "xstore.title": "Messages entre succursales",
  "xstore.help": "Toutes les personnes de ce compte, dans toutes vos entreprises, dans une seule boîte de réception. Écrivez à n'importe laquelle d'entre elles ici — par texte ou par message vocal, avec les indicateurs de livraison et de lecture. Vos Messages en magasin restent tels quels.",
  "xstore.empty": "Aucune conversation pour l'instant. Commencez-en une avec Nouveau message.",
  "xstore.noPeople": "Il n'y a encore personne d'autre à qui écrire. Les gens apparaissent ici dès qu'ils se joignent à l'une de vos entreprises et qu'ils ouvrent une session.",
  "xstore.deliveredLabel": "Livré",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Les messages entre succursales font partie du forfait Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Cette personne ne fait pas partie de ce compte.",
  "training.lessons.owner-xstore-messages.title": "Des messages entre vos succursales, pour les propriétaires",
  "training.lessons.owner-xstore-messages.step1": "Les messages entre succursales sont une deuxième boîte de réception, distincte de Messages. Messages sert pour la succursale où vous vous trouvez; cette porte vous permet de joindre toutes les personnes de votre compte, dans chaque entreprise que vous possédez — jusqu'à cinq.",
  "training.lessons.owner-xstore-messages.step2": "Ouvrez Messages entre succursales à partir du menu et commencez une conversation avec n'importe quelle personne de la liste. La liste montre chaque membre de l'équipe, dans toutes vos entreprises, qui a ouvert une session, avec les succursales où il travaille.",
  "training.lessons.owner-xstore-messages.step3": "Les photos accompagnent les noms : chaque personne montre sa photo de profil approuvée, ou ses initiales si elle n'en a pas. Chaque message indique la date et l'heure de son envoi.",
  "training.lessons.owner-xstore-messages.step4": "Sous vos propres messages, vous pouvez voir Livré dès qu'un message arrive, et Lu dès que l'autre personne ouvre la conversation. Les messages vocaux fonctionnent aussi ici, exactement comme dans Messages.",
  "training.lessons.owner-xstore-messages.step5": "Les conversations ici sont privées entre les deux personnes qui y participent. Votre surveillance des Messages en magasin ne s'étend pas d'une succursale à l'autre.",
  "training.lessons.mgr-xstore-messages.title": "Des messages entre vos succursales, pour les gestionnaires",
  "training.lessons.mgr-xstore-messages.step1": "Les messages entre succursales permettent de joindre toutes les personnes de ce compte, dans toutes les entreprises — pas seulement la succursale où vous vous trouvez. Ils se trouvent dans le menu, séparés de Messages.",
  "training.lessons.mgr-xstore-messages.step2": "Commencez une conversation à partir de la liste : chaque membre de l'équipe qui a ouvert une session y figure, avec les succursales où il travaille à côté de son nom.",
  "training.lessons.mgr-xstore-messages.step3": "Envoyez un texte, ou enregistrez un message vocal. Avant l'envoi d'un message vocal, vous pouvez l'écouter, le jeter ou l'envoyer — comme dans Messages.",
  "training.lessons.mgr-xstore-messages.step4": "Vos messages affichent Livré quand ils arrivent et Lu quand l'autre personne ouvre la conversation. La photo à côté de chaque nom est la photo de profil approuvée de cette personne.",
  "training.lessons.staff-xstore-messages.title": "Des messages entre vos succursales",
  "training.lessons.staff-xstore-messages.step1": "Les messages entre succursales vous permettent de joindre n'importe quelle personne de ce compte, dans n'importe quelle entreprise du propriétaire — une question pour une autre succursale n'a plus à attendre.",
  "training.lessons.staff-xstore-messages.step2": "Ouvrez-les à partir du menu, choisissez la personne et écrivez. Si la personne qu'il vous faut n'est pas dans la liste, elle n'a pas encore ouvert de session — elle apparaîtra dès qu'elle le fera.",
  "training.lessons.staff-xstore-messages.step3": "Vous pouvez aussi envoyer des messages vocaux ici : enregistrez, écoutez, puis envoyez ou jetez. Chaque message affiche la date et l'heure de son envoi.",
  "training.lessons.staff-xstore-messages.step4": "Quand vous envoyez un message, il affiche Livré dès qu'il arrive, et Lu dès que l'autre personne ouvre la conversation. Une conversation est privée entre vous et l'autre personne.",
