  "training.lessons.owner-restaurant-ops.title": "Exploitation du restaurant, pour les propriétaires",
  "training.lessons.owner-restaurant-ops.step1": "Les factures de fournisseurs vivent dans le coin Restaurant. Entrez ce qu'un fournisseur a facturé, lié à son bon de commande, et l'application le vérifie en trois points — commandé, reçu et facturé, côte à côte — et signale toute ligne en moins, en trop, ou facturée à un autre prix.",
  "training.lessons.owner-restaurant-ops.step2": "Quand une ligne de facture facture un produit à un prix différent du coût enregistré, une alerte de prix s'ouvre sur la page des factures. Accepter une alerte met le coût du produit au prix facturé ; l'ignorer laisse le coût tel quel.",
  "training.lessons.owner-restaurant-ops.step3": "Le registre des pertes consigne tout ce que la cuisine jette, avec une raison — produit avarié, surproduction, erreur de préparation, retour, renversé, ou autre — et le consigner retire le stock de l'étagère tout seul. Les lots d'expiration sont listés premier expiré, premier sorti, pour que la date limite la plus proche soit utilisée d'abord, et vous pouvez imprimer les étiquettes de date des lots que vous cochez.",
  "training.lessons.owner-restaurant-ops.step4": "La matrice des allergènes calcule les allergènes de chaque plat à partir des ingrédients de sa recette, face aux neuf principaux allergènes, pour répondre à la question d'un client à partir des données, pas de mémoire. Les relevés de température, le tableau des articles en rupture et les repas des employés sont ouverts à toute l'équipe — aucune case à cocher n'est requise — parce que la consignation quotidienne ne marche que si tout le monde peut la faire.",
  "training.lessons.owner-restaurant-ops.step5": "L'ingénierie de menu place chaque plat selon ses ventes et ses gains : étoiles, chevaux de trait, énigmes et chiens. La page des écarts compare ce que les recettes disent qui aurait dû quitter l'étagère avec les repas des employés, les pertes et tout le reste qui est sorti — ce qui reste est inexpliqué. L'exportation comptable rassemble les achats reçus, les pertes, les repas des employés et la consommation des recettes dans un seul grand livre pour vos livres.",
  "training.lessons.staff-restaurant-daily.title": "Les habitudes quotidiennes de la cuisine",
  "training.lessons.staff-restaurant-daily.step1": "Quand quelque chose est jeté, consignez-le dans le registre des pertes le jour même : ce que c'était, en quelle quantité, et la raison — produit avarié, surproduction, erreur de préparation, retour, renversé, ou autre. Le consigner retire le stock de l'étagère tout seul ; vous n'ajustez pas le stock séparément.",
  "training.lessons.staff-restaurant-daily.step2": "Enregistrez la température de chaque réfrigérateur, congélateur et zone de maintien au chaud au moment du contrôle. Le journal garde votre nom et l'heure, et signale tout relevé hors de la plage sûre — écrivez ce que vous avez fait à ce sujet comme mesure corrective.",
  "training.lessons.staff-restaurant-daily.step3": "Le tableau des articles en rupture, c'est ce qui est en rupture, en ce moment. Affichez un article dès qu'il vient à manquer, pour que toute l'équipe le sache aussitôt, et retirez-le quand il est de retour — le tableau garde qui l'a retiré et quand.",
  "training.lessons.staff-restaurant-daily.step4": "Quand l'équipe mange, enregistrez-le comme repas des employés. Chaque repas retire son plat de l'étagère et utilise les ingrédients de la recette du plat, comme une vente. Un repas des employés est un coût réel de la journée, et il a sa place au registre.",
  "training.lessons.mgr-restaurant-invoices.title": "Factures, lots et productions par lots",
  "training.lessons.mgr-restaurant-invoices.step1": "Le propriétaire vous a confié la case Créer des recettes, et elle ouvre aussi le travail de construction de la cuisine : les factures fournisseurs, les lots de péremption et la production par lots. Saisissez une facture fournisseur avec ses lignes — le produit, la quantité et le coût facturé — et liez-la à son bon de commande quand il y en a un.",
  "training.lessons.mgr-restaurant-invoices.step2": "Avec un bon de commande lié, la facture est vérifiée en trois points, ligne par ligne : ce qui a été commandé, ce qui a été reçu et ce qui a été facturé. Une ligne peut revenir conforme, en moins, en trop, facturée à un autre prix, ou absente de la commande.",
  "training.lessons.mgr-restaurant-invoices.step3": "Quand un prix facturé diffère du coût enregistré du produit, une alerte de prix s'ouvre. Accepter l'alerte met le coût du produit au nouveau prix facturé ; l'ignorer ne change rien. Une seule alerte ouverte à la fois pour la même facture et le même produit.",
  "training.lessons.mgr-restaurant-invoices.step4": "Recevez le stock comme un lot d'expiration avec sa date limite d'utilisation, et la page d'expiration garde les lots premier expiré, premier sorti. Une production par lots prépare une recette un nombre défini de fois : elle consomme les ingrédients de la recette et met le produit de préparation fini sur l'étagère — la recette doit d'abord être liée à ce produit de préparation.",
  "training.lessons.mgr-restaurant-invoices.step5": "Quand un fournisseur rembourse une partie d’une facture — une caisse abîmée, une livraison incomplète, un prix corrigé — inscrivez-le comme un avoir sur la page des factures, contre cette facture. Le fournisseur vient de la facture elle-même, et l’avoir compte contre ce qui reste dû sur la facture : la facture affiche son crédit appliqué et son solde dû. Un crédit ne peut jamais dépasser sa facture, et annuler un avoir le garde au registre pendant qu’il cesse de compter. Imprimez la note depuis sa ligne quand vous en avez besoin sur papier — la feuille imprimée est votre propre registre du crédit du fournisseur, pas le document du fournisseur.",
  "training.lessons.mgr-restaurant-reports.title": "Ingénierie de menu, écarts et les livres",
  "training.lessons.mgr-restaurant-reports.step1": "Le propriétaire vous a confié la case Argent des plats, et elle ouvre aussi les rapports d'argent de la cuisine : l'ingénierie de menu, les écarts et l'exportation comptable. Ces chiffres restent dans l'entreprise, comme tout l'argent des plats.",
  "training.lessons.mgr-restaurant-reports.step2": "L'ingénierie de menu place chaque plat selon ses ventes et ses gains sur la période. Les étoiles se vendent bien et gagnent bien ; les chevaux de trait se vendent bien mais gagnent peu ; les énigmes gagnent bien mais se vendent peu ; les chiens ne font ni l'un ni l'autre.",
  "training.lessons.mgr-restaurant-reports.step3": "La page des écarts travaille par produit : ce que les recettes disent qui aurait dû quitter l'étagère, à côté des repas des employés, des pertes et de toutes les autres sorties de stock. Ce qui reste est inexpliqué — et l'inexpliqué, c'est le chiffre à aller expliquer.",
  "training.lessons.mgr-restaurant-reports.step4": "L'exportation comptable est un seul grand livre pour la cuisine : achats reçus, pertes, repas des employés et consommation des recettes, chaque ligne avec sa date, sa quantité et son coût, prêt à remettre à la personne qui tient vos livres.",
