  "nav.storefronts": "Connexions aux boutiques",
  "plansLib.includes.ebaySync": "Connexion à la boutique eBay — les ventes mettent à jour votre inventaire toutes seules",
  "storefronts.applied": "Enregistrer les ventes en attente",
