  "storefronts.disconnect": "Déconnecter",
  "storefronts.disconnectNote": "La déconnexion empêche les nouvelles ventes d'arriver. Les ventes déjà enregistrées restent dans votre historique.",
  "storefronts.ebayDesc": "Connectez votre boutique eBay une seule fois. Quand un article se vend sur eBay, sa quantité diminue ici toute seule, et la vente est enregistrée dans vos mouvements — comme s'il avait été scanné à la sortie. Les ventes ne circulent que dans un sens : d'eBay vers l'application.",
  "storefronts.ebayTitle": "eBay",
  "storefronts.flashChecked": "Vérifié — {count} nouvelle(s) vente(s) enregistrée(s).",
