  "checklists.starterOpening": "Ouverture",
  "checklists.starterClosing": "Fermeture",
  "checklists.starterCleaning": "Nettoyage",
  "checklists.starterOpeningItem1": "Déverrouillez les portes et éteignez l'alarme",
  "checklists.starterOpeningItem2": "Allumez les lumières et vérifiez que le sol est propre et sûr",
  "checklists.starterOpeningItem3": "Ouvrez la caisse et comptez le fonds de caisse",
  "checklists.starterClosingItem1": "Comptez le fonds de caisse et fermez la caisse",
  "checklists.starterClosingItem2": "Nettoyez et rangez chaque espace",
  "checklists.starterClosingItem3": "Verrouillez les portes et activez l'alarme",
  "checklists.starterCleaningItem1": "Essuyez tous les comptoirs et surfaces",
  "checklists.starterCleaningItem2": "Balayez et lavez les sols",
  "checklists.starterCleaningItem3": "Sortez les poubelles et remplacez les sacs",
  "apiErrors.checklistsManage": "Seul le propriétaire, ou une personne à qui le propriétaire a donné la coche des modèles de listes, peut modifier les modèles de listes.",
  "apiErrors.checklistProof": "Cet élément a besoin de sa preuve avant de pouvoir être coché.",
  "apiErrors.checklistName": "Donnez un nom à la liste.",
  "apiErrors.checklistItems": "Ajoutez au moins un élément à la liste.",
  "apiErrors.checklistUntick": "Seule la personne qui a coché cet élément, un responsable ou le propriétaire peut le décocher.",
  "training.lessons.staff-checklists.title": "Travailler sur une liste de contrôle",
  "training.lessons.staff-checklists.step1": "Les listes de contrôle sont les listes sur lesquelles votre entreprise tourne — ouverture, fermeture, nettoyage, et tout ce que le propriétaire met en place. Trouvez-les sous Listes de contrôle : celles du jour sont en haut, prêtes à cocher.",
  "training.lessons.staff-checklists.step2": "Cochez un élément quand vous l'avez vraiment fait. Chaque coche note qui l'a fait et quand, pour que la personne suivante — et le propriétaire depuis chez lui — voie ce qui est fait et ce qui manque encore.",
  "training.lessons.staff-checklists.step3": "Certains éléments demandent une preuve avant de pouvoir être cochés : une photo du travail terminé, un scan d'un code, ou une température tapée. Ajoutez d'abord la preuve, puis cochez — l'élément ne se cochera pas sans elle.",
  "training.lessons.staff-checklists.step4": "Vous avez coché quelque chose par erreur ? Décochez-le — mais seulement vos propres coches. Un responsable ou le propriétaire peut décocher celles de n'importe qui, parce qu'une coche est un enregistrement avec un nom.",
  "training.lessons.staff-checklists.step5": "Vous n'avez jamais besoin d'une permission pour travailler sur une liste. Créer les modèles et choisir à qui ils sont affectés, c'est le travail du propriétaire, ou d'une personne à qui le propriétaire a donné la coche des modèles de listes.",
