  "foodSafety.mock.intro": "Lancez une inspection fictive et cochez chaque point sur la page des listes au fur et à mesure. Chaque coche consigne qui a contrôlé et quand — corrigez ce que vous trouvez en chemin, et le dossier montrera le travail.",
  "foodSafety.mock.startButton": "Lancer l’inspection fictive du jour",
