  "foodSafety.mock.openChecklists": "Ouvrir les listes",
  "foodSafety.mock.item1": "Les réfrigérateurs, congélateurs et le maintien au chaud sont dans leurs plages sûres, et le journal des températures est rempli.",
  "foodSafety.mock.item2": "Les contrôles de refroidissement et de remise en température sont consignés, avec une action corrective là où un relevé a manqué.",
  "foodSafety.mock.item3": "La solution désinfectante est mélangée à la bonne concentration et son contrôle est consigné.",
  "foodSafety.mock.item4": "Tous les certificats alimentaires sont en cours de validité, et les renouvellements sont en cours pour ceux qui expirent bientôt.",
