  "foodSafety.mock.item8": "Le journal des déchets est à jour, avec un motif pour tout ce qui a été jeté.",
  "training.lessons.staff-food-safety.title": "Tenir le dossier de sécurité alimentaire",
  "training.lessons.staff-food-safety.step1": "Le dossier de sécurité alimentaire se trouve sur l’étagère Sécurité alimentaire du Coin restaurant : journaux de températures, journaux de refroidissement, de remise en température et de désinfectant, certificats, fiches de données de sécurité et dossier d’inspection.",
  "training.lessons.staff-food-safety.step2": "Un relevé hors plage n’est terminé que lorsque sa note dit ce que vous avez fait — refroidir à nouveau, remettre en température, refaire le désinfectant, jeter. Pas de note, pas d’enregistrement : l’entrée ne tient pas.",
  "training.lessons.staff-food-safety.step3": "Consignez les contrôles de refroidissement, de remise en température et de désinfectant comme les températures : ce que vous avez contrôlé, le relevé, et l’action corrective en cas d’échec.",
  "training.lessons.staff-food-safety.step4": "Les certificats avertissent avant d’expirer. Quand le vôtre avertit, dites-le au propriétaire — et tout le monde peut lire les fiches de données de sécurité sur leur étagère, à tout moment.",
  "training.lessons.staff-food-safety.step5": "Avant une inspection — ou à tout moment — lancez l’inspection fictive depuis l’étagère Sécurité alimentaire et imprimez le dossier prêt pour l’inspection aux dates de l’inspecteur.",
