  "training.lessons.staff-equipment.step1": "Chaque machine de votre entreprise a sa propre page sous Équipement : quand elle a été achetée, quand sa garantie se termine, qui l’entretient et tout ce qui lui est arrivé.",
  "training.lessons.staff-equipment.step2": "Quand quelque chose casse, signalez-le sur la machine elle-même. Dites ce qui est cassé et ajoutez une photo du problème si vous le pouvez : le signalement entre dans l’historique de la machine avec votre nom et l’heure.",
  "training.lessons.staff-equipment.step3": "Vous ne pouvez signaler une panne que si le propriétaire vous a donné l’autorisation de signalement. Si le bouton n’est pas là, prévenez le propriétaire ou un responsable et ils vous ouvriront la porte.",
  "training.lessons.staff-equipment.step4": "Les tâches d’entretien — nettoyage, détartrage, révision — ont des dates d’échéance. La page Équipement montre ce qui est dû et ce qui est en retard, pour que rien ne glisse en silence.",
  "training.lessons.staff-equipment.step5": "Les réparations et leur coût sont enregistrés par le propriétaire ou un responsable. Une fois la réparation enregistrée sur votre signalement, la panne apparaît comme réparée dans l’historique de la machine.",
  "nav.tipPooling": "Pot commun des pourboires",
