  "training.lessons.owner-tip-pooling.title": "Le pot des pourboires et le registre des pourboires",
  "training.lessons.owner-tip-pooling.step1": "Ouvrez Restaurant, puis Équipe et lieu, puis Pot commun des pourboires. Seul le propriétaire voit la configuration du pot, les parts et les registres.",
  "training.lessons.owner-tip-pooling.step2": "Choisissez comment le pot est réparti : par heures, par pourcentage selon le rôle ou par points. L'application répartit à partir de l'horaire et des heures pointées déjà présents.",
  "training.lessons.owner-tip-pooling.step3": "Choisissez la période, saisissez le montant du pot, prévisualisez la répartition, puis enregistrez-la. Les parts enregistrées alimentent l'aperçu de la paie pour cette période.",
  "training.lessons.owner-tip-pooling.step4": "Publiez une répartition enregistrée quand vous êtes prêt — un membre de l'équipe ne verra alors que sa propre part, et rien avant votre publication.",
  "training.lessons.owner-tip-pooling.step5": "Tenez le registre des pourboires au fur et à mesure : par personne et par période, les pourboires déclarés — et le registre de l'année convertit le calcul des 8 % en totaux prêts pour le formulaire. L'application ne garde que des registres ; elle ne dépose rien.",
