  "apiErrors.laborOwner": "Seul le propriétaire peut fixer les chiffres de surveillance de la main-d'œuvre.",
  "apiErrors.laborSettings": "Vérifiez les chiffres de surveillance de la main-d'œuvre et réessayez.",
  "training.lessons.owner-labor-warnings.title": "Régler les alertes de main-d'œuvre",
  "training.lessons.owner-labor-warnings.step1": "Ouvrez le planning et trouvez les chiffres de surveillance. Chaque chiffre est le vôtre, à fixer pour votre propre établissement.",
  "training.lessons.owner-labor-warnings.step2": "Fixez les heures hebdomadaires où les heures supplémentaires commencent pour vous, et à quelle distance quelqu'un peut s'approcher avant que l'application ne vous alerte.",
  "training.lessons.owner-labor-warnings.step3": "Fixez quand une pause est attendue dans un quart et sa durée, ainsi que le début le plus tôt et la fin la plus tard que vous voulez pour les quarts.",
  "training.lessons.owner-labor-warnings.step4": "Construisez la semaine comme d'habitude. Les alertes apparaissent sur le planning à mesure que les heures approchent de vos lignes — avant de les franchir.",
  "training.lessons.owner-labor-warnings.step5": "À mesure que votre équipe pointe ses entrées et sorties, la même surveillance passe sur les heures déjà travaillées, y compris les pauses qui n'ont pas été prises.",
  "training.lessons.owner-labor-target.title": "Construire la semaine face à un objectif de main-d'œuvre",
  "training.lessons.owner-labor-target.step1": "Ouvrez Objectif de main-d'œuvre sur l'étagère Équipe et lieu du Coin restaurant.",
  "training.lessons.owner-labor-target.step2": "Saisissez votre objectif de main-d'œuvre en pourcentage, et les ventes que vous attendez pour la semaine.",
  "training.lessons.owner-labor-target.step3": "Construisez la semaine sur le planning. Le coût de main-d'œuvre prévu et le % se mettent à jour à partir des quarts et des taux déjà dans l'application.",
  "training.lessons.owner-labor-target.step4": "Quand le % de main-d'œuvre prévu dépasse votre objectif, la page le dit en mots simples, avec les heures et le coût derrière.",
  "training.lessons.owner-labor-target.step5": "Imprimez la semaine depuis la page quand vous la voulez sur papier — la feuille imprimée est le même document que celui à l'écran.",
  "nav.cateringEvents": "Traiteur et événements",
