  "training.lessons.owner-catering-events.title": "Réserver un événement traiteur",
  "training.lessons.owner-catering-events.step1": "Ouvrez Traiteur et événements sur l'étagère Salle et invités du Coin restaurant.",
  "training.lessons.owner-catering-events.step2": "Ajoutez l'événement : son nom, sa date et son heure, le nombre d'invités, et le nom et le téléphone de l'hôte.",
  "training.lessons.owner-catering-events.step3": "Choisissez le menu parmi vos propres plats et fixez les portions de chacun.",
