  "training.lessons.owner-catering-events.step5": "Imprimez la fiche d'événement pour la cuisine et la salle — la copie personnel ne montre pas l'argent — et regardez la Mise en place, où les aliments de l'événement apparaissent déjà.",
  "nav.reservations": "Réservations",
  "plansLib.businessIncludes.reservations": "Réservations et liste d'attente — le cahier de réservations, la liste d'attente de ce soir et les rappels que le client a demandés",
