  "staff.memberDialog.reservationsAccessHint": "Avec cette coche, cette personne peut prendre les réservations et tenir la liste d'attente de ce soir — le travail d'accueil. Sans elle, le cahier est en lecture seule pour elle. Le propriétaire et les gérants peuvent toujours tenir le cahier.",
