  "reservations.bookNote": "Ceci est un cahier, pas la salle en direct : il ne suit pas les tables minute par minute et il n'y a pas de réservation en ligne — chaque ligne a été prise par votre équipe, par téléphone ou à la porte.",
  "reservations.hostNote": "Prendre les réservations, c'est le travail d'accueil : le propriétaire, un gérant ou une personne à qui le propriétaire a donné la coche d'accueil. Les numéros et courriels des clients vivent uniquement dans ce cahier.",
