  "apiErrors.waitlistInvalid": "Vérifiez les détails de la liste d'attente et réessayez.",
  "training.lessons.owner-reservations.title": "Prendre les réservations et tenir la liste d'attente",
  "training.lessons.owner-reservations.step1": "Ouvrez Réservations sur l'étagère Salle et invités du Coin restaurant. Le cahier garde chaque réservation ; la liste d'attente en dessous garde les clients sans réservation de ce soir.",
  "training.lessons.owner-reservations.step2": "Ajoutez une réservation avec la date et l'heure, le nom et la taille du groupe, un numéro de téléphone et la table ou la section dans vos propres mots. Notez ce que la cuisine doit savoir — une allergie, une chaise haute, un anniversaire.",
  "training.lessons.owner-reservations.step3": "Demandez au client s'il veut un rappel et cochez la case seulement quand il dit oui. Les rappels partent par courriel, et par texto quand les textos sont configurés. Inscrivez tout acompte déjà reçu — combien et comment — comme un simple relevé.",
  "training.lessons.owner-reservations.step4": "Travaillez le cahier pendant la soirée : marquez chaque groupe installé, absent ou annulé. Envoyez la liste du jour à l'équipe depuis le cahier pour que tout le monde travaille sur la même page.",
  "training.lessons.owner-reservations.step5": "Pour les clients sans réservation, ajoutez le groupe à la liste d'attente avec l'attente annoncée. Quand sa table est prête, touchez Table prête — donner un numéro pour ce texto, c'est le oui du client.",
  "apiErrors.smsInvalid": "Un SMS a besoin d'un numéro et d'un message.",
  "apiErrors.smsFailed": "Le service de SMS n'a pas accepté le message.",
