  "apiErrors.standingOrdersInvalid": "Vérifiez les détails de la commande permanente et réessayez.",
  "training.lessons.owner-standing-orders.title": "Commandes permanentes et comparaison des prix fournisseurs",
  "training.lessons.owner-standing-orders.step1": "Ouvrez Commandes permanentes sur l'étagère Stock et Commandes du Coin Restaurant. Vos commandes récurrentes vivent ici, et en dessous d'elles le livre des prix fournisseurs.",
  "training.lessons.owner-standing-orders.step2": "Configurez une commande permanente une fois : donnez-lui un nom, choisissez son fournisseur et le jour auquel elle correspond, et ajoutez les lignes habituelles avec les quantités que vous commandez d'ordinaire.",
  "training.lessons.owner-standing-orders.step3": "Le jour venu, touchez Créer le brouillon de cette semaine. L'application écrit un bon de commande en brouillon dans les Achats, au dernier prix de ce fournisseur tiré du livre — relisez-le, modifiez ce qu'il faut et envoyez-le vous-même. L'application n'envoie jamais une commande d'elle-même.",
  "training.lessons.owner-standing-orders.step4": "Lisez le livre des prix avant de commander : un ingrédient, le dernier prix de chaque fournisseur côte à côte, le moins cher en premier, avec la date et si le prix vient d'une facture ou d'une commande.",
  "training.lessons.owner-standing-orders.step5": "Gardez le livre à jour en saisissant les factures fournisseurs à leur arrivée — chaque nouveau prix rejoint le livre et le prochain brouillon est calculé à partir de lui.",
  "nav.productionOrder": "Commande selon la production",
