  "productionOrder.subtitle": "Choisissez un plan de production — une production en lot ou un événement traiteur. L'application calcule les ingrédients nécessaires, retire ce qui est déjà en stock et présente le reste sous la forme du guide de commande.",
  "productionOrder.draftNote": "Chaque commande créée par cette page arrive comme un bon de commande en brouillon dans les Achats, pour votre confirmation. L'application n'envoie jamais une commande d'elle-même.",
