  "prepSuggest.title": "Suggestions de préparation",
  "prepSuggest.subtitle": "Quantités suggérées à partir de vos niveaux par, des réservations et de ce qui est déjà préparé. L'application montre ses calculs — rien ne change sur la fiche tant que vous ne lancez pas la production.",
  "prepSuggest.bookedLine": "Réservé : {guests} invités en réservations · {events} événements à venir",
