  "training.lessons.owner-production-order.title": "Commander selon la production et des fiches de préparation qui se remplissent toutes seules",
  "training.lessons.owner-production-order.step1": "Ouvrez Commande selon la production sur l'étagère Stock et commandes du Coin restaurant. Un plan de production — une production en lot ou un événement traiteur — y devient une commande d'ingrédients.",
  "training.lessons.owner-production-order.step2": "Choisissez le plan : une recette et le nombre de fournées pour une production en lot, ou l'un de vos événements traiteur réservés. Touchez Calculer la commande.",
  "training.lessons.owner-production-order.step3": "L'application déploie les recettes, retire ce qui est déjà en stock et arrondit le reste au format d'emballage supérieur, regroupé par fournisseur — la forme du guide de commande.",
  "training.lessons.owner-production-order.step4": "Touchez Créer les commandes en brouillon et un bon de commande en brouillon par fournisseur arrive dans les Achats. Vérifiez-les et envoyez-les vous-même — l'application n'envoie jamais une commande d'elle-même.",
  "training.lessons.owner-production-order.step5": "Sur la page Préparation, la fiche se remplit toute seule : les fournées suggérées viennent de vos niveaux par, des réservations et des événements, et de ce qui est déjà préparé — la suggestion s'affiche et rien ne change tant que vous ne lancez pas la production.",
  "nav.barCounting": "Comptage du bar",
  "restaurant.doorBarCounting": "Comptage du bar — comptez les bouteilles entamées en dixièmes et les fûts de la même façon, par zone de stockage",
  "plansLib.businessIncludes.barCounting": "Comptage du bar pour bouteilles entamées et fûts",
  "barCounting.title": "Comptage du bar",
  "barCounting.subtitle": "Comptez ce qui est entamé, par zone de stockage. Faites glisser jusqu'au niveau de la bouteille ouverte — en dixièmes — et enregistrez les fûts de la même façon. Les bouteilles et fûts pleins comptent en entier.",
  "barCounting.offTitle": "Le comptage du bar est désactivé",
  "barCounting.offBody": "Le comptage du bar reste masqué jusqu'à ce que le propriétaire l'active. Ne l'activez que si cet établissement tient un bar — il apparaît sur l'étagère Stock et commandes.",
