  "barCounting.emptyTitle": "Rien n'est encore stocké dans cette zone",
  "barCounting.emptyBody": "Le comptage du bar compte ce qu'une zone de stockage contient. Ajoutez d'abord du stock à cette zone, puis comptez-y les bouteilles et les fûts.",
  "barCounting.printButton": "Imprimer la feuille de comptage",
  "barCounting.docTitle": "Comptage du bar",
  "barCounting.docArea": "{name}",
  "barCounting.varianceNote": "Un comptage du bar enregistré est une session de comptage : ses écarts avec l'enregistré forment le côté réel de l'écart théorique-réel.",
  "apiErrors.barCountingForbidden": "Seul le propriétaire peut activer ou désactiver le comptage du bar.",
  "apiErrors.barCountingCountForbidden": "Seul le propriétaire, un responsable ou une personne ayant l'autorisation de comptage peut enregistrer un comptage du bar.",
  "apiErrors.barCountingInvalid": "Vérifiez le comptage du bar et réessayez.",
  "apiErrors.barCountingOff": "Le comptage du bar n'est pas activé pour cet établissement.",
  "training.lessons.owner-bar-counting.title": "Compter le bar : bouteilles entamées et fûts",
  "training.lessons.owner-bar-counting.step1": "Activez le comptage du bar depuis l'étagère Stock et commandes — il reste masqué jusqu'à ce que vous le fassiez, donc un établissement sans bar ne le voit jamais. L'interrupteur appartient au seul propriétaire.",
  "training.lessons.owner-bar-counting.step2": "Ouvrez Comptage du bar et choisissez la zone de stockage où vous vous trouvez. La feuille liste ce que la zone contient, avec l'enregistré à côté de chaque bouteille et fût.",
  "training.lessons.owner-bar-counting.step3": "Pour chaque ligne, dites s'il s'agit de bouteilles ou d'un fût, saisissez les pleines, puis faites glisser jusqu'au niveau de celle entamée — en dixièmes, jugé contre son image. Le nombre compté est les pleines plus les dixièmes de l'entamée.",
  "training.lessons.owner-bar-counting.step4": "Enregistrez le comptage du bar. Il arrive dans Comptages comme une session ordinaire — envoyez-le en vérification et appliquez-le là, et l'étagère passe à ce que vous avez compté.",
  "training.lessons.owner-bar-counting.step5": "Les écarts qu'un comptage du bar découvre alimentent l'écart théorique-réel, donc une bouteille qui manque toujours s'y révèle. Imprimez la feuille de comptage depuis cette page quand vous voulez le comptage sur papier.",
