  "training.lessons.owner-locations-rollup.title": "Tous les emplacements sur une page",
  "training.lessons.owner-locations-rollup.step1": "Ouvrez l'étagère Emplacements et choisissez Tous les emplacements. L'étagère elle-même n'apparaît que lorsque vous possédez deux entreprises ou plus, donc un propriétaire d'un seul emplacement ne la voit jamais.",
  "training.lessons.owner-locations-rollup.step2": "Lisez la ligne de chaque emplacement : coût des aliments %, valeur du stock, gaspillage de cette semaine et ce qui est bas. L'emplacement qui ressort est le point faible à traiter en premier.",
  "training.lessons.owner-locations-rollup.step3": "Imprimez la vue d'ensemble quand vous voulez la comparaison sur papier — elle s'imprime comme elle apparaît à l'écran.",
  "training.lessons.owner-locations-rollup.step4": "Pour copier une recette, choisissez-la, cochez les emplacements où elle doit arriver, et copiez. Les ingrédients sont appariés d'abord par SKU, puis par nom ; ce qui n'a aucune correspondance est nommé dans le résultat, jamais écarté en silence.",
  "training.lessons.owner-locations-rollup.step5": "Pour copier les prix, utilisez Copier les prix et les coûts avec les mêmes emplacements cochés. Une recette dont le plat n'a aucune correspondance dans un emplacement y arrive comme brouillon, prête à être liée par vous.",
  "plansLib.businessIncludes.recipeCostLink": "Coûts des recettes qui suivent le prix de facture le plus récent",
