  "ops.invoices.acceptNote": "Accepter une facture fait de ses prix les coûts actuels de ses ingrédients, et chaque recette qui les utilise recalcule son coût — la recette affiche une note nommant le prix de la facture sur lequel elle repose.",
  "training.lessons.owner-recipe-cost-link.title": "Les coûts des recettes suivent les prix des factures",
  "training.lessons.owner-recipe-cost-link.step1": "Saisissez une facture fournisseur comme brouillon pendant que vous la vérifiez par rapport à la livraison.",
  "training.lessons.owner-recipe-cost-link.step2": "Quand la facture est juste, mettez son statut à Acceptée.",
