  "training.lessons.owner-lot-traceability.step1": "Quand une livraison arrive, ouvrez Lots et rappels sur l'étagère Stock et commandes et enregistrez-la : le produit, le fournisseur, la quantité — et le code de lot tamponné sur le carton, par article.",
  "training.lessons.owner-lot-traceability.step2": "Sur le même écran de la porte arrière, notez la température de livraison des produits froids, et tout ce que vous avez refusé et pourquoi. Un refus écrit est la preuve dont un avoir fournisseur a besoin.",
  "training.lessons.owner-lot-traceability.step3": "Pour les produits vendus au poids, enregistrez le poids réel arrivé. L’application calcule le coût réel par livre ou par kilo à partir de celui-ci, pour que les coûts des recettes restent honnêtes.",
  "training.lessons.owner-lot-traceability.step4": "Si un lot est rappelé, retirez-le : le lot se verrouille pour que personne ne puisse l’utiliser, le retrait lui-même devient un enregistrement, et ce qui restait part au journal des pertes avec son motif.",
  "training.lessons.owner-lot-traceability.step5": "Utilisez le chercheur de rappels et le journal de traçabilité pour répondre où se trouve un lot et tout son parcours — par fournisseur ou par lot — et imprimez le journal pour les services de santé ou le fournisseur.",
